 public static void Bind(FrameworkElement element,DependencyProperty property,string key){element.SetResourceReference(property,"Desk"+key);}
 public static void BindTree(DependencyObject item){
  var element=item as FrameworkElement;if(element!=null&&Convert.ToString(element.Tag)=="theme-art")return;
  var text=item as TextBlock;if(text!=null){var brush=text.Foreground as SolidColorBrush;string role=text.FontSize>=16?"Text":"Muted";if(brush!=null){var c=brush.Color;if(c.R==112&&c.G==206&&c.B==233)role="Accent";}Bind(text,TextBlock.ForegroundProperty,role);}
  var control=item as Control;if(control!=null){if(control is Button&&(Convert.ToString(control.Tag)=="primary"||Convert.ToString(control.Tag)=="danger"))control.ClearValue(Control.ForegroundProperty);else Bind(control,Control.ForegroundProperty,control is System.Windows.Controls.Primitives.TextBoxBase||control is PasswordBox?"EditText":"Text");if(control is TextBox||control is ListBox||control is ComboBox){control.ClearValue(Control.BackgroundProperty);control.ClearValue(Control.BorderBrushProperty);}}
  var border=item as Border;if(border!=null){if(border.Background!=null&&border.Background!=Brushes.Transparent)Bind(border,Border.BackgroundProperty,"Surface");if(border.BorderBrush!=null)Bind(border,Border.BorderBrushProperty,"Line");}
  var panel=item as Panel;if(panel!=null){panel.SetResourceReference(TextBlock.ForegroundProperty,"DeskText");if(panel.Background!=null&&panel.Background!=Brushes.Transparent)Bind(panel,Panel.BackgroundProperty,"Inset");}
  var path=item as System.Windows.Shapes.Path;if(path!=null&&path.Stroke!=null)Bind(path,System.Windows.Shapes.Shape.StrokeProperty,"Accent");
  foreach(var child in LogicalTreeHelper.GetChildren(item).OfType<DependencyObject>())BindTree(child);
 }
}

